package com.eventhub.controller; import com.eventhub.dto.CertificateResponse; import com.eventhub.service.CertificateService; import jakarta.servlet.http.HttpServletRequest; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/certificates") @RequiredArgsConstructor public class CertificateController {private final CertificateService service; @PostMapping("/registrations/{registrationId}/generate") public CertificateResponse generate(Authentication a,@PathVariable Long registrationId,HttpServletRequest req){return service.generate(a.getName(),registrationId,req.getRemoteAddr());} @GetMapping("/{id}") public CertificateResponse get(Authentication a,@PathVariable Long id){return service.get(a.getName(),id);} @GetMapping("/{id}/pdf") public ResponseEntity<byte[]> pdf(Authentication a,@PathVariable Long id)throws Exception{return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=eventhub-certificate-"+id+".pdf").body(service.pdf(a.getName(),id));} @GetMapping("/verify/{certificateId}") public CertificateResponse verify(@PathVariable String certificateId){return service.verify(certificateId);}}
